UPDATE alphafrog_agent_run
SET plan_json = COALESCE(CAST(#{planJson} AS jsonb), plan_json),
    status = #{status},
    snapshot_json = CAST(#{snapshotJson} AS jsonb),
    completed_at = CASE WHEN #{completed} THEN CURRENT_TIMESTAMP ELSE completed_at END,
    last_error = #{lastError},
    updated_at = CURRENT_TIMESTAMP
WHERE id = #{id}
  AND user_id = #{userId}
  AND deployment_id = #{deploymentId}
  AND deployment_generation_id = #{deploymentGenerationId}
  AND status = 'EXECUTING'
  AND tool_job_anchor_json #>> '{resumeState}' IN ('LAUNCHING', 'ACCEPTED')
  AND COALESCE((tool_job_anchor_json #>> '{resultConsumed}')::boolean, false)
  AND tool_job_anchor_json #>> '{resumeToken}' = #{expectedResumeToken}
  AND (tool_job_anchor_json #>> '{resumeLeaseVersion}')::bigint = #{expectedLeaseVersion}
  AND tool_job_anchor_json #>> '{resumeLauncherOwnerId}' = #{expectedLauncherOwnerId}
  AND (tool_job_anchor_json #>> '{resumeLauncherLeaseUntil}')::timestamptz
        > CURRENT_TIMESTAMP
  AND COALESCE((tool_job_anchor_json ->> 'autoResume')::boolean, true)

